//! Expression plotter: your own functions, with a control for every parameter.
//!
//! Generated by Formula from the rows of an Expression plotter. Explicit rows are
//! y = f(x), polar rows are r = f(theta), parametric rows are (x(t), y(t)). The
//! parts between the @ markers are what changes from one export to the next.
//! Tab picks a parameter, Up/Down change it, drag to pan, scroll to zoom.
//!
//! Cargo.toml:
//!     [dependencies]
//!     macroquad = "0.4"
//! Run: cargo run --release

use macroquad::prelude::*;

/// A parameter with its slider range.
struct Param {
    name: &'static str,
    value: f64,
    min: f64,
    max: f64,
}

/// One row of the plot: y = f(x), or a curve (x, y) = f(t) for t in t0..t1.
enum Row {
    Explicit(Box<dyn Fn(f64) -> f64>),
    Curve(Box<dyn Fn(f64) -> (f64, f64)>, f64, f64),
}

fn params() -> Vec<Param> {
    vec![
// @PARAMS
        Param { name: "a", value: 2.0, min: -10.0, max: 10.0 },
        Param { name: "b", value: 1.0, min: -10.0, max: 10.0 },
        Param { name: "k", value: 3.0, min: -10.0, max: 10.0 },
// @END
    ]
}

fn value(p: &[Param], name: &str) -> f64 {
    p.iter().find(|q| q.name == name).map_or(0.0, |q| q.value)
}

/// A polar point (r, theta) as (x, y).
fn polar(r: f64, theta: f64) -> (f64, f64) {
    (r * theta.cos(), r * theta.sin())
}

/// Every row of the plot, for the current parameter values.
fn rows(p: &[Param]) -> Vec<Row> {
// @EXPRESSIONS
    let a = value(p, "a");
    let b = value(p, "b");
    let k = value(p, "k");
    vec![
        Row::Explicit(Box::new(move |x: f64| a * (b * x).sin())),
        Row::Curve(Box::new(move |theta: f64| polar(1.0 + (k * theta).cos(), theta)), 0.0, 6.283185307179586),
    ]
// @END
}

/// Draws a polyline, lifting the pen where a point is not finite or jumps
/// by more than five view heights (an asymptote).
fn curve(points: &[(f64, f64)], to_screen: &dyn Fn(f64, f64) -> Vec2, span: f64, color: Color, dashed: bool) {
    let mut prev: Option<(f64, f64)> = None;
    for (i, &(x, y)) in points.iter().enumerate() {
        if !(x.is_finite() && y.is_finite()) {
            prev = None;
            continue;
        }
        let y = y.clamp(-1e6, 1e6);
        if let Some((px, py)) = prev {
            if (y - py).abs() <= 5.0 * span && !(dashed && i % 4 >= 2) {
                let (a, b) = (to_screen(px, py), to_screen(x, y));
                draw_line(a.x, a.y, b.x, b.y, 2.0, color);
            }
        }
        prev = Some((x, y));
    }
}

#[macroquad::main("Expression plotter")]
async fn main() {
    let mut params = params();
    let mut selected = 0usize;
    let (mut cx, mut cy, mut scale) = (0.0_f64, 0.0_f64, 0.01_f64);
    let mut last_mouse = mouse_position();
    let colors = [
        Color::from_rgba(157, 179, 255, 255),
        Color::from_rgba(92, 194, 178, 255),
        Color::from_rgba(227, 169, 59, 255),
    ];

    loop {
        if is_key_pressed(KeyCode::Tab) && !params.is_empty() {
            selected = (selected + 1) % params.len();
        }
        if let Some(p) = params.get_mut(selected) {
            let step = (p.max - p.min) / 100.0;
            if is_key_down(KeyCode::Up) {
                p.value = (p.value + step).min(p.max);
            }
            if is_key_down(KeyCode::Down) {
                p.value = (p.value - step).max(p.min);
            }
        }
        let mouse = mouse_position();
        if is_mouse_button_down(MouseButton::Left) {
            cx -= (mouse.0 - last_mouse.0) as f64 * scale;
            cy += (mouse.1 - last_mouse.1) as f64 * scale;
        }
        last_mouse = mouse;
        let wheel = mouse_wheel().1 as f64;
        if wheel != 0.0 {
            scale *= (-wheel * 0.1).exp();
        }

        let (w, h) = (screen_width() as f64, screen_height() as f64);
        let to_screen = |x: f64, y: f64| vec2((w / 2.0 + (x - cx) / scale) as f32, (h / 2.0 - (y - cy) / scale) as f32);
        clear_background(Color::from_rgba(22, 32, 28, 255));
        let origin = to_screen(0.0, 0.0);
        let axis = Color::from_rgba(85, 99, 93, 255);
        draw_line(0.0, origin.y, w as f32, origin.y, 1.0, axis);
        draw_line(origin.x, 0.0, origin.x, h as f32, 1.0, axis);

        for (i, row) in rows(&params).iter().enumerate() {
            let points: Vec<(f64, f64)> = match row {
                Row::Explicit(f) => (0..=w as usize)
                    .map(|px| {
                        let x = cx + (px as f64 - w / 2.0) * scale;
                        (x, f(x))
                    })
                    .collect(),
                Row::Curve(f, t0, t1) => (0..=720).map(|j| f(t0 + (t1 - t0) * j as f64 / 720.0)).collect(),
            };
            curve(&points, &to_screen, h * scale, colors[i % 3], i >= 3);
        }

        for (i, p) in params.iter().enumerate() {
            let mark = if i == selected { ">" } else { " " };
            let text = format!("{mark} {} = {:.3}   [{}, {}]", p.name, p.value, p.min, p.max);
            draw_text(&text, 16.0, 24.0 + 20.0 * i as f32, 20.0, WHITE);
        }
        draw_text("Tab: next parameter   Up/Down: change it   drag: pan   wheel: zoom", 16.0, h as f32 - 12.0, 18.0, GRAY);
        next_frame().await;
    }
}
